function productSuggestionList(context=productSearchContext){return $(context?.collection==='edit'?'#editProductSuggestions':'#productSuggestions')}
function hideProductSuggestions(){productMatches=[];activeProductMatch=-1;productSearchContext=null;$$('.product-suggestions').forEach(list=>{list.classList.add('role-hidden');list.innerHTML=''})}
function renderProductSuggestions(input,context){const query=normalizeSearch(input.value.trim());if(query.length<2){hideProductSuggestions();return}const seen=new Set();productMatches=productDirectory.filter(product=>product.searchPartNo.includes(query)).sort((a,b)=>Number(b.searchPartNo.startsWith(query))-Number(a.searchPartNo.startsWith(query))||String(a.partNo).localeCompare(String(b.partNo),'tr')).filter(product=>{const key=`${product.partNo}|${product.description}`;if(seen.has(key))return false;seen.add(key);return true}).slice(0,8);activeProductMatch=-1;productSearchContext=context;const list=productSuggestionList(context);if(!productMatches.length){hideProductSuggestions();return}list.innerHTML=productMatches.map((product,index)=>`<button type="button" role="option" data-product-suggestion-index="${index}"><strong>${escapeHtml(product.partNo)}</strong><span>${escapeHtml(product.description)}</span><small>${escapeHtml(product.source)}${product.itemNo?` · Item No: ${escapeHtml(product.itemNo)}`:''}</small></button>`).join('');const rect=input.getBoundingClientRect(),width=Math.min(window.innerWidth-20,580,Math.max(380,rect.width*2.4)),left=Math.max(10,Math.min(rect.left,window.innerWidth-width-10));list.style.left=`${left}px`;list.style.top=`${Math.max(10,Math.min(rect.bottom+4,window.innerHeight-330))}px`;list.style.width=`${width}px`;list.classList.remove('role-hidden')}
function selectProductSuggestion(product){if(!product||!productSearchContext)return;const {collection,index}=productSearchContext,target=collection==='draft'?draftOrderProducts:editOrderProducts,rowTarget=collection==='draft'?'#orderProductRows':'#editOrderProductRows';if(!target[index])return;target[index].partNo=product.partNo;target[index].description=product.description;hideProductSuggestions();if(collection==='draft')renderOrderProducts();else renderEditOrderProducts();$(`${rowTarget} input[data-${collection==='draft'?'product':'edit-product'}-index="${index}"][data-${collection==='draft'?'product':'edit-product'}-field="qty"]`)?.focus()}
function handleProductSuggestionKey(event,collection,index){if(!productSearchContext||productSearchContext.collection!==collection||productSearchContext.index!==index||!productMatches.length)return false;if(event.key==='ArrowDown'){event.preventDefault();activeProductMatch=(activeProductMatch+1)%productMatches.length}else if(event.key==='ArrowUp'){event.preventDefault();activeProductMatch=(activeProductMatch-1+productMatches.length)%productMatches.length}else if(event.key==='Enter'&&activeProductMatch>=0){event.preventDefault();selectProductSuggestion(productMatches[activeProductMatch]);return true}else if(event.key==='Escape'){event.preventDefault();hideProductSuggestions();return true}else return false;const buttons=$$(`${collection==='edit'?'#editProductSuggestions':'#productSuggestions'} button`);buttons.forEach((button,buttonIndex)=>button.classList.toggle('active',buttonIndex===activeProductMatch));buttons[activeProductMatch]?.scrollIntoView({block:'nearest'});return true}
function detailValue(value){return value===undefined||value===null||value===''?'—':escapeHtml(value)}
