function detailSetGroups(products){if(!products.length)return '<div class="empty-set-state">Set bilgisi bulunmuyor.</div>';const groups=new Map();products.forEach(product=>{const name=product.setInfo?.trim()||'Set atanmamış';if(!groups.has(name))groups.set(name,[]);groups.get(name).push(product)});return `<div class="set-groups detail-set-groups">${[...groups.entries()].map(([name,items])=>`<section class="set-group"><div class="set-group-header"><strong>${escapeHtml(name)}</strong><span>${items.length} ürün</span></div>${items.map(product=>`<div class="set-product"><b>${detailValue(product.partNo)}</b><span>${detailValue(product.description)}</span><em>${detailValue(product.qty)} adet</em></div>`).join('')}</section>`).join('')}</div>`}
function serviceVisitsDetail(visits=[]){if(!visits.length)return '<p class="detail-empty">Henüz servis kurulum kaydı girilmemiş.</p>';return `<div class="service-visit-summary">${visits.map(visit=>`<article><h4>${visit.visitNumber}. Kurulum <span>${visit.completed?'Tamamlandı':'Devam edecek'}</span></h4><div class="detail-grid">${detailField('Teknisyenler',(visit.technicians||[]).join(', '))}${detailField('Müşteri katılımcıları',(visit.customerParticipants||[]).join(', '))}${detailField('Yol süresi',`${visit.travelDuration||0} ${visit.travelUnit||'Saat'}`)}${detailField('Saha süresi',`${visit.siteDuration||0} ${visit.siteUnit||'Saat'}`)}${detailField('Check-list',visit.checklistStatus)}${detailField('Ürün durumu',visit.productStatus==='missing'?'Ürün eksik':visit.productStatus==='demo'?'Demo ürün':'Ürünler tam')}${detailField('Eksik ürünler',(visit.missingProducts||[]).join(', '))}${detailField('Demo ürün notu',visit.demoProductNote)}${detailField('Sonraki kurulum',visit.nextInstallationDate)}${detailField('Rapor paylaşıldı',visit.reportShared?'Evet':'Hayır')}${detailField('Paylaşılan e-mail',visit.sharedEmailAttachment?.name)}</div>${visit.notes?`<div class="detail-note"><span>Kurulum notu</span><p>${escapeHtml(visit.notes)}</p></div>`:''}<div class="detail-files">${(visit.attachments||[]).length?visit.attachments.map(file=>`<span>${escapeHtml(file.name)}</span>`).join(''):'<em>Kurulum raporu veya dosya eklenmemiş.</em>'}</div></article>`).join('')}</div>`}
