  <section class="detail-section"><h3>Müşteri ve sipariş</h3><div class="detail-grid">${detailField('Müşteri',item.customer)}${detailField('Müşteri yapısı',isMtb?'MTB ve son kullanıcı ayrı':'Doğrudan son kullanıcı')}${isMtb?detailField('MTB firma',item.mtbName)+detailField('Son kullanıcı firma',item.endUserName):''}${detailField('Satış mühendisi',item.salesEngineer)}${detailField('SO No',item.salesOrderNumber)}${detailField('PTD No',item.ptd)}${detailField('Kurulum tutarı',Number.isFinite(Number(item.installationAmount))?new Intl.NumberFormat('tr-TR',{style:'currency',currency:'EUR'}).format(item.installationAmount):'—')}${detailField('Talep tarihi',item.requestDate)}</div></section>
